INSERT INTO `info_page` (`id`, `type`, `title`, `data`) VALUES (1,1,'Реинкорнация','Я решил восстановить старый проект, чуть позже перепилю его как надо.<br><br>Что уже сделано:<br>- поднят локальный стек на Docker (MySQL, Flyway, PHP 5.6, nginx, cron);<br>- схема и данные схлопнуты в три миграции: структура, каталог, тестовые игроки;<br>- Flash-клиент заменён на Cosmic SPA (Svelte): персонаж, место, корабли, склад, торговля, чат, энциклопедия;<br>- карты планет и орбит снова валидные (сетка 50×50, как в gensystem);<br>- админка вынесена в отдельный терминал /admin/ с JSON API и 404 для не-админов;<br>- в галактике пока два пилота — sharque и test — со своими системами и флотами.<br><br>Добро пожаловать обратно.');
/*!40000 ALTER TABLE `info_page` ENABLE KEYS */;
UNLOCK TABLES;

