INSERT INTO `messages` (`hash`, `ru`) VALUES ('60bae3738ccea0e6b6e1523c555cf498','Астрономы зафиксировали странный корабль <font color=\"#00FF00\">в системе %s корабль</font> в рабочем состоянии, но не отвечает на опознавательные запросы.'),('d71a1e2feaf771a10d858b33aae23ce4','Астрономы обнаружили малый объект <font color=\"#FF0000\">в вашей системе в точке %d:%d. Предположительно, это тритит</font>.'),('11dc3f6720ec22da7b7fc701dac3e06d','ВНИМАНИЕ !!! Зафиксирован несанкционированный доступ к складу торговой станции. Согласно записи стерео наблюдения это был дед в красной шубе. Способ проникновения остался неизвестен.'),('e95d330c3916f566348961ed2e3b85bb','Привет, это Дед Мороз, индейцы Майа так меня перепугали, что пока в бункер, пока обратно - не успел я на новый год к тебе, но попутно нашел другой календарь, где новый год значится сегодня. Собственно подарок я принес как пологается, не серчай на Деда за опоздание.\n\nPS:подарок лежит на станции, распаковать сможешь на планете, надеюсь он тебе понравится.\nДед Мороз.'),('1c0839dbf7d33a10745f680476bb188d','Все подарки раздал\n\nДед Мороз.'),('b98801fb67c7b83c59e7b2f9ca534002','пропащий'),('a276932ae67ee49087b9232b93202755','невезучий'),('5e366ed2360a22baa9fa11d320f4ebdc','страшный неудачник'),('9cecbc4e6a7f9a8ed2f898c41421eab6','неудачник'),('36c8047be1e6057296450348649a1fdb','гражданский'),('3303b1a88750b6912c141d2c97ce4b78','Матрос'),('c1a7c4343ab642167f368114fd81fd16','Старший матрос'),('334e1e6a2a3b929d2685fa9c78e7e21e','Старшина'),('e091e67cb686eb26361a39586a816b7b','Мичман'),('cfccb6fe51606ee8e530c16a115ac35c','Лейтенант'),('ce6d1855c82ca96ef77a5a5b5b7db627','Капитан'),('de224f05a923159bd189938650332ea0','Командор'),('5b3b0a40540e117fe6dbd9d39cb93ce5','Контр-адмирал'),('56fa7a4a5f1785631c1acbfcfdc4dc12','Вице-адмирал'),('fd0ee5b2a3c0287bf646217a9157228f','Адмирал'),('5530327bc5fc151481de41150f4ed5af','Адмирал флота'),('0dc4ef942f8b7b9ef018b688f616777d','Маршал флота'),('e60cec8a407e7ed22e851cff6680485f','враг