INSERT INTO `quest_types` (`type`, `name`, `desc`, `status`, `cnt`, `arg0`, `arg1`, `arg2`, `arg3`, `arg4`, `arg5`, `arg6`, `arg7`, `arg8`, `arg9`, `gen_date`) VALUES (1,'Для постройки корабля требуется %arg5 в количестве %arg1. Награда %arg3 кредитов.','Конфедерация нашла макет неизвестного корабля и для испытания надо построить этот корабль, ваша помощь может оказаться очень кстати, требуется %arg5 в количестве %arg1. Конфедерация готова заплатить %arg3 кредитов тому, кто поможет с добычей. Конфедерация позаботится и доставит его самостоятельно с вашей родной планеты. Конфедерация всегда помнит о тех, кто оказывает помощь, ваш уровень ответственности изменится соответственно.',2,3,'null','(round(rand()*40)+10)*100','%seed%%49+1000','round(arg1 / 10)','round(arg1 / 100)','(SELECT name FROM objects WHERE id = %seed%%49+1000)','null','null','null','null','0000-00-00 00:00:00'),(2,'Найти потерянный корабль в системе %arg4. Награда %arg2 кредитов.','Не так давно из системы %arg4 поступил сигнал экстренной помощи, сигнал был очень слабым и точные координаты корабля установить не удалось. Если вы готовы помочь, вам будет необходим радарный корабль и транспортный корабль с топливом. Нужно переместится в систему %arg4, отыскать корабль и объединится с кораблем в флот. От вас требуется доставить корабль до ближайшей планеты где есть станция конфедерации и состыковаться со станцией. В качестве вознаграждения вы получите %arg2 кредитов и благодарность от спасенных людей. Конфедерация всегда помнит о тех, кто оказывает помощь, ваш уровень ответственности изменится соответственно.',6,5,'null','(SELECT star_id FROM planets WHERE user_id IS NOT NULL ORDER BY rand(%seed%) LIMIT 0,1)','round(rand()*40+10)*100','round(arg2/10)','(SELECT s.name FROM planets p INNER JOIN stars s ON s.id = p.star_id WHERE p.user_id IS NOT NULL ORDER BY rand(%seed%) LIMIT 0,1)','null','null','null','null','null','0000-00-00 00:00:00'),(3,'Перевезти пакет из системы %arg1 в систему %arg3. Награда %arg4 кредитов','Некоторые сведения нельзя доверять гиперпередаче и требуется доброволец для доставки секретных сведений. Пакет содержит цифровой монокристалл который практически не поддается расшифровке. Вам необходимо пристыковаться к торговой станции в звездной системе %arg1 после проверки вашего корабля вам лично в руки будет передан пакет. Ваша задача как можно быстрее добраться до системы %arg3 и пристыковаться к торговой станции. Награда %arg4 кредитов. Вам необходимо ЛИЧНО присутствовать на корабле.',5,3,'(SELECT star_id FROM planets WHERE user_id IS NOT NULL ORDER BY rand(%seed%) LIMIT 0,1)','(SELECT s.name FROM planets p INNER JOIN stars s ON s.id = p.star_id WHERE p.user_id IS NOT NULL ORDER BY rand(%seed%) LIMIT 0,1)','(SELECT star_id FROM planets WHERE user_id IS NOT NULL ORDER BY rand(%seed%+13) LIMIT 0,1)','(SELECT s.name FROM planets p INNER JOIN stars s ON s.id = p.star_id WHERE p.user_id IS NOT NULL ORDER BY rand(%seed%+13) LIMIT 0,1)','round(rand()*50+50)*100','round(arg4/100)','null','null','(SELECT star_id FROM planets WHERE user_id IS NOT NULL ORDER BY rand(%seed%+25) LIMIT 0,1)','(SELECT s.name FROM planets p INNER JOIN stars s ON s.id = p.star_id WHERE p.user_id IS NOT NULL ORDER BY rand(%seed%+25) LIMIT 0,1)','0000-00-00 00:00:00'),(4,'Уничтожить %arg2 Трититов в системе %arg1. Награда %arg3 кредитов','В системе %arg1 активизировались Трититы, силы конфедерации далеко от звезды и поэтому требуется ваша помощь. Необходимо собрать флот и отправится в систему %arg1, нам необходимо быть уверенными в положительном исходе войны. По данным разведки в системе %arg1 обнаружено %arg2 Трититов, но конфедерация не располагает точными сведениями о боевой мощи этого флота.',4,3,'(SELECT id FROM stars ORDER BY rand(%seed%) LIMIT 0,1)','(SELECT name FROM stars ORDER BY rand(%seed%) LIMIT 0,1)','round(rand()*17+3)','round(arg2*100)','null','null','null','null','null','null','0000-00-00 00:00:00'),(5,'Для торговой станции требуется %arg5 в количестве %arg1. Награда %arg3 кредитов.','Конфедерация исследуя новые рубежи галактики постоянно занята строительством торговых станций однако случаются нападения пиратов и Трититов на транспортные корабли, от чего часть ресурсов теряется. Для завершения постройки торговой станции требуется %arg5 в количестве %arg1. Конфедерация готова заплатить %arg3 кредитов тому, кто поможет с добычей. Конфедерация позаботится и доставит его самостоятельно с вашей родной планеты. Конфедерация всегда помнит о тех, кто оказывает помощь, ваш уровень ответственности изменится соответственно.',2,3,'null','(round(rand()*40)+10)*100','%seed%%49+1000','round(arg1 / 10)','round(arg1 / 100)','(SELECT name FROM objects WHERE id = %seed%%49+1000)','null','null','null','null','0000-00-00 00:00:00'),(6,'Добыть %arg5 в количестве %arg1. Награда %arg3 кредитов.','Конфедерации планет требуется ваша помощь. В настоящий момент все производственные мощности работают в полную силу, однако требуется еще %arg5 в количестве %arg1. Конфедерация готова заплатить %arg3 кредитов тому, кто поможет с добычей. Конфедерация позаботится и доставит его самостоятельно с вашей родной планеты. Конфедерация всегда помнит о тех, кто оказывает помощь, ваш уровень ответственности изменится соответственно.',2,3,'null','(round(rand()*40)+10)*100','%seed%%49+1000','round(arg1 / 10)','round(arg1 / 100)','(SELECT name FROM objects WHERE id = %seed%%49+1000)','null','null','null','null','0000-00-00 00:00:00'),(7,'Требуется минерал %arg5 в количестве %arg1. Награда %arg3 кредитов.','Для экспериментов на глюоном ускорителе требуется чистый минерал %arg5 в количестве %arg1. От результатов эксперимента зависит будущее науки. Конфедерация готова заплатить %arg3 кредитов тому, кто поможет с добычей. Конфедерация позаботится и доставит его самостоятельно с вашей родной планеты. Конфедерация всегда помнит о тех, кто оказывает помощь, ваш уровень ответственности изменится соответственно.',2,1,'null','(round(rand()*10)+10)*100','(SELECT id FROM objects WHERE class = 5 ORDER BY rand(%seed%) LIMIT 1,1)','round(arg1 / 2)','round(arg1 / 100)','(SELECT name FROM objects WHERE class = 5 ORDER BY rand(%seed%) LIMIT 1,1)','null','null','null','null','0000-00-00 00:00:00'),(8,'Предотвратите вторжение армии Трититов в системе %arg1. Награда %arg3 кредитов','В системе %arg1 обнаружено сильное искажение пространства Трититы объединились в армию и начали уничтожение всего живого, силы конфедерации далеко от звезды и поэтому требуется ваша помощь. Необходимо собрать сильный флот и отправится в систему %arg1, нам необходимо быть уверенными в положительном исходе войны. По данным разведки в системе %arg1 обнаружено не менее %arg2 Трититов, но конфедерация не располагает точными сведениями о боевой мощи этого флота.',4,3,'(SELECT id FROM stars WHERE type != 4 ORDER BY rand(%seed%) LIMIT 0,1)','(SELECT name FROM stars WHERE type != 4 ORDER BY rand(%seed%) LIMIT 0,1)','round(rand()*50+20)','round(arg2*100)','null','null','null','null','null','null','0000-00-00 00:00:00'),(9,'Освободите оккупированную планету %arg3 в системе %arg1 вознаграждение %arg5 кредитов','В системе %arg1 пираты оккупировали и удерживают под своим контролем планету %arg1 Конфедерация не вмешивается во внутренние конфликты, однако готова выплатить %arg5 кредитов за вашу помощь в освобождении планеты. По данным предварительной разведки на орбите находится %arg4 кораблей. Будьте предусмотрительны, пираты могут не дать вам второго шанса.',4,3,'(SELECT s.id FROM planets p LEFT JOIN orbits_buildings ob ON ob.planet_id = p.id LEFT JOIN stars s ON s.type != 4 AND p.star_id = s.id WHERE p.user_id IS NULL AND ob.id IS NULL ORDER BY rand(%seed%) LIMIT 0,1)','(SELECT s.name FROM planets p LEFT JOIN orbits_buildings ob ON ob.planet_id = p.id LEFT JOIN stars s ON s.type != 4 AND p.star_id = s.id WHERE p.type IN( 2, 3, 4 ) AND ob.id IS NULL ORDER BY rand(%seed%) LIMIT 0,1)','(SELECT p.id FROM planets p LEFT JOIN orbits_buildings ob ON ob.planet_id = p.id LEFT JOIN stars s ON s.type != 4 AND p.star_id = s.id WHERE p.type IN( 2, 3, 4 ) AND ob.id IS NULL ORDER BY rand(%seed%) LIMIT 0,1)','(SELECT p.name FROM planets p LEFT JOIN orbits_buildings ob ON ob.planet_id = p.id LEFT JOIN stars s ON s.type != 4 AND p.star_id = s.id WHERE p.type IN( 2, 3, 4 ) AND ob.id IS NULL ORDER BY rand(%seed%) LIMIT 0,1)','round(rand()*35+35)','round(arg4*100)','null','null','null','null','0000-00-00 00:00:00'),(12,'Исследовать неизвестную точку в пространстве. Координаты %arg2 x %arg3. Награда %arg0','Автоматические разведчики конфедерации заметили странное искажение в пространстве. Вам предоставляется честь исследовать точку в пространстве. Помните, что завершение этой миссии в любом случае необходимо для конфедерации. Точка в пространстве с координатами %arg2:%arg3 излучает слишком много энергии, а плотность вещества в этой точке значительно превышает плотность космического вакуума. От этого задания нельзя будет отказаться, в случае неудачи вам придется воспользоваться помощью других пилотов. Награда %arg0',2,1,'round(rand()*25000) + 5000','round(rand()*6)','round(sin(rand(%seed%)*7)*(rand(%seed%+10)*100+700))','round(cos(rand(%seed%)*7)*(rand(%seed%+10)*100+700))','null','null','null','null','null','null','0000-00-00 00:00:00'),(13,'Переломить ход между пиратами и конфедерацией. В точке пространства %arg2 x %arg3. Награда %arg0','Корабли конфедерации, во время патрулирования, обнаружили флот пиратов. Силы двух противостоящих флотов практически равны. Обе стороны не решаются начать бой зная, что в живых не останется никто. У вас есть возможность встать на сторону конфедерации или пиратов и переломить ход этой битвы! Торопитесь, противник тоже собирает подмогу и битва вот-вот начнется. Координаты столкновения %arg2:%arg3 это точка в гиперпространстве. Как поступить с союзниками противника решать вам. Главное это исход назначенного сражения. Конфедерация предлагает вам награду в %arg0 кредитов за то, что вы встанете на их сторону. Учтите, до окончания битвы нельзя будет отказаться от этого задания. Вам придется дождаться конца сражения.',3,1,'round(rand()*2500) + 5000','null','round(sin(rand(%seed%)*7)*(rand(%seed%+10)*100+700))','round(cos(rand(%seed%)*7)*(rand(%seed%+10)*100+700))','null','null','null','null','null','null','0000-00-00 00:00:00'),(14,'Переломить ход между пиратами и конфедерацией. В точке пространства %arg2 x %arg3. Награда %arg0','В гиперпространстве столкнулись флота конфедерации и пиратов. К ним уже примкнуло подкрепление! У вас есть шанс внести свой вклад в эту битву. Чем быстрее вы отправитесь на эту битву, тем больше у вас шансов. У вас есть возможность встать на сторону конфедерации или пиратов и переломить ход этой битвы! Координаты столкновения %arg2:%arg3 это точка в гиперпространстве. Как поступить с союзниками противника решать вам. Главное это исход назначенного сражения. Конфедерация предлагает вам награду в %arg0 кредитов за то, что вы встанете на их сторону. Учтите, до окончания битвы нельзя будет отказаться от этого задания. Вам придется дождаться конца сражения.',3,0,'null','null','null','null','null','null','null','null','null','null','0000-00-00 00:00:00'),(16,'Переместить планету','Обмен/перемещение планет между пилотами.',4,0,'null','null','null','null','null','null','null','null','null','null','0000-00-00 00:00:00'),(17,'Уничтожить орбитальную оборону','Уничтожение орбитальной обороны указанной планеты.',2,0,'null','null','null','null','null','null','null','null','null','null','0000-00-00 00:00:00'),(18,'Уничтожить планетарную оборону','Уничтожение планетарной обороны указанной планеты.',2,0,'null','null','null','null','null','null','null','null','null','null','0000-00-00 00:00:00'),(19,'Построить карьеры','Постройка карьеров на указанной планете.',3,0,'null','null','null','23','Карьер','null','null','null','null','null','0000-00-00 00:00:00'),(20,'Построить шахты','Постройка шахт на указанной планете.',3,0,'null','null','null','36','Шахта','null','null','null','null','null','0000-00-00 00:00:00'),(21,'Построить буровые','Постройка буровых на указанной планете.',3,0,'null','null','null','37','Буровая','null','null','null','null','null','0000-00-00 00:00:00'),(22,'Построить нанодиспенсеры','Постройка нанодиспенсеров на указанной планете.',3,0,'null','null','null','24','Нанодиспенсер','null','null','null','null','null','0000-00-00 00:00:00'),(23,'Построить планетарные щиты','Постройка планетарных щитов на указанной планете.',3,0,'null','null','null','31','Планетарный щит','null','null','null','null','null','0000-00-00 00:00:00'),(24,'Построить ракетную защиту','Постройка ракетной защиты на указанной планете.',3,0,'null','null','null','27','Ракетная защита','null','null','null','null','null','0000-00-00 00:00:00'),(25,'Построить лазерную защиту','Постройка лазерной защиты на указанной планете.',3,0,'null','null','null','28','Лазерная защита','null','null','null','null','null','0000-00-00 00:00:00'),(26,'Построить плазменную защиту','Постройка плазменной защиты на указанной планете.',3,0,'null','null','null','29','Плазменная защита','null','null','null','null','null','0000-00-00 00:00:00'),(27,'Построить коротковолновые мазеры','Постройка коротковолновых мазеров на указанной планете.',3,0,'null','null','null','30','Коротковолновый мазер','null','null','null','null','null','0000-00-00 00:00:00'),(28,'Улучшить все постройки +1 уровень','Повышение уровня всех построек на планете на 1.',3,0,'null','null','null','null','null','null','null','null','null','null','0000-00-00 00:00:00'),(29,'Улучшить все постройки до 10 уровня','Повышение уровня всех построек на планете до 10.',3,0,'null','null','null','null','null','null','null','null','null','null','0000-00-00 00:00:00'),(31,'Найти колонию пилота','Поиск колонии указанного пилота.',2,0,'null','null','null','null','null','null','null','null','null','null','0000-00-00 00:00:00'),(33,'Вызвать на дуэль','Вызов пилота на дуэль с ограничениями флота.',4,0,'null','null','null','null','null','null','null','null','null','null','0000-00-00 00:00:00');
